def main():
 files={}
 for p,expected in MANIFEST['files'].items():
  with urllib.request.urlopen(BASE+p,timeout=20) as response:b=response.read(1048577)
  if len(b)>1048576 or hashlib.sha256(b).hexdigest()!=expected:raise ValueError('DOWNLOAD_SOURCE_SHA256_MISMATCH')
